//! Tests for the committed Round 10 example golden.
//!
//! The golden forks reading of the standing example meet is
//! regenerated by the forks command itself, and these pins
//! fail if the example, the golden, or the reading drifts
//! away from the hand computed forks of the standing meet, and
//! the reconciliation pins read the reign reading over the
//! same file and fail when the forks reading disagrees with
//! it over the spells and the counts.

use std::fs;
use std::path::PathBuf;

use paceghost::cli::dispatch;
use paceghost::meet::{load_meet_file, meet_forks, meet_reign};
use paceghost::pytext::PText;

fn reader(bytes: &[u8]) -> Option<String> {
    let path = String::from_utf8_lossy(bytes).into_owned();
    let data = std::fs::read(path).ok()?;
    String::from_utf8(data).ok()
}

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

#[test]
fn test_the_example_forks_match_the_golden_bytes() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_forks(&meet).expect("the example forks read");
    let golden =
        fs::read_to_string(examples.join("meet-forks-golden.txt")).expect("the golden file reads");
    let golden_lines: Vec<&str> = golden.lines().collect();
    assert_eq!(lines, golden_lines);
    assert!(golden.ends_with('\n'));
}

#[test]
fn test_the_forks_command_prints_the_golden_forks() {
    let examples = examples_dir();
    let golden =
        fs::read_to_string(examples.join("meet-forks-golden.txt")).expect("the golden file reads");
    let golden_lines: Vec<String> = golden.lines().map(str::to_string).collect();
    let argv: Vec<PText> = vec![
        PText::from_text("forks"),
        PText::from_text(examples.join("meet.json").to_str().unwrap()),
    ];
    let outcome = dispatch(&argv, &reader);
    assert_eq!(outcome.code, 0);
    assert_eq!(outcome.stdout, golden_lines);
    assert!(outcome.stderr.is_empty());
}

#[test]
fn test_the_example_forks_close_on_the_hand_counts() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_forks(&meet).expect("the example forks read");
    // The hand counts of the standing meet, computed from the
    // one walk. Operator sets six standings and holds two
    // spells and stands at all sixteen marks, night fork sets
    // six standings and holds one spell and stands at fifteen
    // marks, dawn fork sets four standings and holds two
    // spells and stands at fourteen marks, and quiet fork
    // stands in one day and sets no standing at all.
    assert_eq!(lines[0], "meet forks, 3 days, 4 competitors");
    let closes: Vec<&String> = lines
        .iter()
        .filter(|line| line.starts_with("close, "))
        .collect();
    assert_eq!(
        closes,
        vec![
            "close, days stood in 3, marks stood at 16, spells held 2, standing projection 750 at the close",
            "close, days stood in 3, marks stood at 15, spells held 1, standing projection 720 at the close",
            "close, days stood in 3, marks stood at 14, spells held 2, standing projection 560 at the close",
            "close, days stood in 1, marks stood at 0, spells held 0, no standing projection at the close",
        ]
    );
    assert_eq!(
        lines.last().map(String::as_str),
        Some("forks counts, competitors 4, marks stood at 45, spells 5")
    );
}

#[test]
fn test_the_example_section_spells_agree_with_the_reign_spells() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_forks(&meet).expect("the example forks read");
    let reign = meet_reign(&meet).expect("the reign reads");
    // Each section's spell lines are the reign spell lines of
    // that holder in reign order with the holder label read
    // off, dawn fork and operator holding two apiece, so the
    // two readings state one list of spells cut two ways.
    for label in ["operator", "night fork", "dawn fork", "quiet fork"] {
        let section = lines
            .iter()
            .skip_while(|line| line.as_str() != format!("competitor {}", label))
            .skip(1)
            .take_while(|line| {
                !line.starts_with("competitor ") && !line.starts_with("forks counts")
            })
            .filter_map(|line| line.strip_prefix("spell, "))
            .map(|rest| format!("spell, {}, {}", label, rest))
            .collect::<Vec<String>>();
        let reign_of_holder: Vec<String> = reign
            .iter()
            .filter(|line| line.starts_with(&format!("spell, {}, ", label)))
            .map(|line| line.to_string())
            .collect();
        assert_eq!(section, reign_of_holder, "the spells of {}", label);
    }
    let reign_counts = reign.last().expect("the reign counts line stands");
    assert!(reign_counts.contains("spells 5"));
    assert!(lines
        .last()
        .expect("the forks counts line stands")
        .ends_with("spells 5"));
}
